/*
 * Purpose:
 * Find the largest n-digit pandigital prime.
 *
 * A pandigital number contains each digit from 1 to n exactly
 * once. All pandigital numbers are generated and tested for
 * primality, and the largest prime encountered is returned.
 *
 * Approach:
 * Pandigital candidates are generated by building permutations
 * of the digits 1 to 9. A sieve is then used to generate the
 * prime numbers required for trial division. The candidate list
 * is searched from largest to smallest until a prime is found.
 */
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ProjectEulerProblem41 {
    class Program {
        static List<int> primes = new List<int>();

        static void Main(string[] args) {
            // Stores all generated pandigital numbers.
            List<int> candidates = new List<int>();

            // Working lists used during permutation generation.
            List<int> next = new List<int>();
            List<int> prev = new List<int>();

            candidates.Add(1);
            prev.Add(1);

            // Generate pandigital numbers of increasing length.
            for (int i = 2; i <= 9; i++) {
                next.Clear();

                for (int j = 0; j < prev.Count; j++) {
                    int temp = prev[j];
                    int length = 0;
                    int rotate = 1;

                    // Determine the number of digits.
                    while (temp  != 0) {
                        length++;
                        temp /= 10;
                        rotate *= 10;
                    }

                    // Insert the new digit into every possible position.
                    temp = prev[j] * 10 + i;
                    for (int k = 0; k <= length; k++) {
                        candidates.Add(temp);
                        next.Add(temp);

                        // Rotate digits to generate the next permutation.
                        temp = (temp % rotate) * 10 + temp / rotate;
                    }
                }

                // Prepare for the next digit length.
                prev.Clear();
                for (int j = 0; j < next.Count; j++) {
                    prev.Add(next[j]);
                }
                next.Clear();
            }

            // Sort candidates so they can be searched in descending order.
            candidates.Sort();

            // Generate primes required for primality testing.
            primes.Add(2);
            bool[] sieve = new bool[(int)(Math.Sqrt(candidates[candidates.Count - 1])/2)];
            Array.Clear(sieve, 0, sieve.Length);

            for(int i = 1; i < sieve.Length; i++) {
                if(!sieve[i]) {
                    int number = i * 2 + 1;
                    primes.Add(number);

                    // Mark multiples as composite.
                    for (int j = i + number; j < sieve.Length; j+= number) {
                        sieve[j] = true;
                    }
                }
            }

            // Search from largest to smallest candidate.
            int index = candidates.Count;
            bool found = false;
            while(!found) {
                index--;

                if(isPrime(candidates[index])) {
                    found = true;
                }
            }

            // Display the largest pandigital prime.
            Console.WriteLine(candidates[index]);
            Console.ReadLine();
        }

        /*
         * Determines whether a candidate number is prime using
         * trial division by previously generated prime numbers.
         */
        public static bool isPrime(int number) {
            int lastDigit = number % 10;

            // Exclude values ending in an even digit or 5.
            if (lastDigit % 2 != 2 && lastDigit % 2 != 5) {
                int limit = (int)Math.Sqrt(number);

                // Test divisibility by known primes.
                for (int i = 0; i < primes.Count && primes[i] <= limit; i++) {
                    if (number % primes[i] == 0) {
                        return false;
                    }
                }
            } else {
                return false;
            }

            return true;
        }
    }
}